from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    result = []
    for i in range(h // 2):
        row = []
        for j in range(w // 2):
            block = [grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]]
            counts = Counter(block)
            if len(counts) == 1:
                row.append(grid[i][j])  # all same
            else:
                min_count = min(counts.values())
                minorities = [v for v, c in counts.items() if c == min_count]
                row.append(min(minorities))
        result.append(row)
    return result
